import {esc,icon} from './ui.js';
const words={zh:{brand:'企盈智擎',brandSub:'订单经营分析平台',headline:'让每一笔订单，经营有数',intro:'连接生产数据，洞察利润变化',login:'登录',register:'注册',welcome:'欢迎回来',welcomeSub:'登录您的账号，进入订单经营工作空间',create:'创建您的账号',createSub:'从数据出发，开启更清晰的经营决策',account:'账号或邮箱',accountHint:'请输入账号或邮箱',password:'密码',passwordHint:'请输入密码',passwordNew:'设置密码（8–128 位）',confirm:'确认密码',confirmHint:'请再次输入密码',captcha:'图形验证码',captchaHint:'请输入图中字符',refresh:'点击换一张验证码',remember:'保持登录',submitLogin:'登录并进入项目',submitRegister:'创建账号',noAccount:'还没有账号？',hasAccount:'已有账号？',registerLink:'立即注册',loginLink:'返回登录',show:'显示密码',hide:'隐藏密码',loading:'正在处理…',captchaLoading:'正在载入验证码…',success:'注册成功，请登录您的账号。',footer:'企盈智擎 · 数据驱动经营',local:'本机项目工作空间',network:'连接失败，请检查网站服务后重试',mismatch:'两次输入的密码不一致',INVALID_CAPTCHA:'验证码错误或已过期，请输入新验证码',INVALID_ACCOUNT:'账号须为 3–64 位英文、数字或 _ @ . + -',INVALID_PASSWORD:'密码长度须为 8–128 位',ACCOUNT_EXISTS:'该账号已注册，请登录或使用其他账号',INVALID_CREDENTIALS:'账号或密码错误',RATE_LIMITED:'操作过于频繁，请稍后重试',FORBIDDEN:'请求来源无效，请从本站页面操作',AUTH_UNAVAILABLE:'账号服务暂不可用，请稍后重试',INVALID_REQUEST:'输入有误，请检查后重试'},en:{brand:'QIYING',brandSub:'Order Intelligence Platform',headline:'Clarity for every order',intro:'Connect production data. Understand your profit.',login:'Log in',register:'Sign up',welcome:'Welcome back',welcomeSub:'Sign in to your order intelligence workspace',create:'Create your account',createSub:'Start making clearer decisions with your data',account:'Username or email',accountHint:'Enter your username or email',password:'Password',passwordHint:'Enter your password',passwordNew:'Create a password (8–128 characters)',confirm:'Confirm password',confirmHint:'Re-enter your password',captcha:'Image verification',captchaHint:'Enter the characters',refresh:'Refresh verification image',remember:'Keep me signed in',submitLogin:'Log in to workspace',submitRegister:'Create account',noAccount:'New to Qiying?',hasAccount:'Already have an account?',registerLink:'Create an account',loginLink:'Log in',show:'Show password',hide:'Hide password',loading:'Please wait…',captchaLoading:'Loading image…',success:'Account created. Please log in.',footer:'Qiying · Decisions driven by data',local:'Local project workspace',network:'Connection failed. Check the website service and retry.',mismatch:'Passwords do not match',INVALID_CAPTCHA:'Incorrect or expired code. Enter the new code.',INVALID_ACCOUNT:'Use 3–64 letters, numbers or _ @ . + -',INVALID_PASSWORD:'Password must contain 8–128 characters',ACCOUNT_EXISTS:'This account already exists. Log in or use another account.',INVALID_CREDENTIALS:'Incorrect username or password',RATE_LIMITED:'Too many attempts. Please try again later.',FORBIDDEN:'Invalid request origin. Please use this website.',AUTH_UNAVAILABLE:'Account service is unavailable. Please retry later.',INVALID_REQUEST:'Please check your input and try again.'}};
export function mountAuth(root,{initialMode='login',onLogin,client=fetch}={}){
 let alive=true,mode=initialMode,lang='zh',challenge=null,busy=false,captchaBusy=false,notice='',error='',showPassword=false,version=0,values={username:'',password:'',confirm:'',captcha:'',remember:false};
 try{lang=localStorage.getItem('qiying-auth-language')==='en'?'en':'zh';}catch{}
 const t=key=>words[lang][key]??words[lang].INVALID_REQUEST;
 const rememberValues=()=>{const form=root.querySelector('#auth-form');if(!form)return;for(const name of ['username','password','confirm','captcha'])if(form.elements[name])values[name]=form.elements[name].value;values.remember=form.elements.remember?.checked??false;};
 function render(){if(!alive)return;document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=t(mode)+' · '+t('brand');const reg=mode==='register';
 root.innerHTML=`<div class="auth-atmosphere" aria-hidden="true"><i></i><i></i><i></i></div><header class="auth-header"><a class="auth-brand" href="#login"><img src="assets/qiying-logo.jpg" alt="企盈智擎 QIYING ZHIQING"><span><strong>${t('brand')}</strong><small>${t('brandSub')}</small></span></a><div class="auth-language" role="group" aria-label="Language / 语言"><button type="button" data-lang="zh" aria-pressed="${lang==='zh'}" class="${lang==='zh'?'active':''}">中文</button><button type="button" data-lang="en" aria-pressed="${lang==='en'}" class="${lang==='en'?'active':''}">EN</button></div></header><main class="auth-main" id="main"><div class="auth-heading"><span class="auth-eyebrow">QIYING INTELLIGENCE</span><h1>${t('headline')}</h1><p>${t('intro')}</p></div><section class="auth-card" aria-label="${t(mode)}"><div class="auth-tabs"><button type="button" data-mode="login" class="${!reg?'active':''}" aria-pressed="${!reg}">${t('login')}</button><button type="button" data-mode="register" class="${reg?'active':''}" aria-pressed="${reg}">${t('register')}</button></div><div class="auth-card-heading"><h2>${t(reg?'create':'welcome')}</h2><p>${t(reg?'createSub':'welcomeSub')}</p></div><form id="auth-form"><label class="auth-label" for="auth-account">${t('account')}</label><div class="auth-input-wrap">${icon('user')}<input id="auth-account" name="username" autocomplete="username" placeholder="${t('accountHint')}" value="${esc(values.username)}" minlength="3" maxlength="64" required autocapitalize="none" spellcheck="false"></div><label class="auth-label" for="auth-password">${t('password')}</label><div class="auth-input-wrap">${icon('lock')}<input id="auth-password" name="password" type="${showPassword?'text':'password'}" autocomplete="${reg?'new-password':'current-password'}" placeholder="${t(reg?'passwordNew':'passwordHint')}" value="${esc(values.password)}" minlength="8" maxlength="128" required><button class="auth-reveal" type="button" id="auth-reveal" aria-label="${t(showPassword?'hide':'show')}" aria-pressed="${showPassword}"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" stroke="currentColor" stroke-width="1.5"/><circle cx="12" cy="12" r="3" stroke="currentColor" stroke-width="1.5"/></svg></button></div>${reg?`<label class="auth-label" for="auth-confirm">${t('confirm')}</label><div class="auth-input-wrap">${icon('lock')}<input id="auth-confirm" name="confirm" type="${showPassword?'text':'password'}" autocomplete="new-password" placeholder="${t('confirmHint')}" value="${esc(values.confirm)}" minlength="8" maxlength="128" required></div>`:''}<label class="auth-label" for="auth-captcha">${t('captcha')}</label><div class="auth-captcha-row"><div class="auth-input-wrap">${icon('check')}<input id="auth-captcha" name="captcha" autocomplete="off" placeholder="${t('captchaHint')}" value="${esc(values.captcha)}" maxlength="4" minlength="4" required spellcheck="false"></div><button id="auth-captcha-refresh" type="button" class="auth-captcha-image" aria-label="${t('refresh')}" title="${t('refresh')}" ${captchaBusy?'disabled':''}>${challenge?`<img src="${challenge.image}" alt="${t('captcha')}">`:`<span>${t('captchaLoading')}</span>`}</button></div>${!reg?`<label class="auth-remember"><input name="remember" type="checkbox" ${values.remember?'checked':''}>${t('remember')}</label>`:''}<div class="auth-message ${error?'error':notice?'success':''}" role="status" aria-live="polite">${esc(error?t(error):notice?t(notice):'')}</div><button class="auth-submit" type="submit" ${busy||!challenge?'disabled':''}>${busy?t('loading'):t(reg?'submitRegister':'submitLogin')}<span aria-hidden="true">→</span></button></form><p class="auth-switch">${t(reg?'hasAccount':'noAccount')}<button type="button" data-mode="${reg?'login':'register'}">${t(reg?'loginLink':'registerLink')}</button></p></section></main>`;
 root.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{rememberValues();lang=b.dataset.lang;try{localStorage.setItem('qiying-auth-language',lang);}catch{}render();});
 root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(busy)return;rememberValues();mode=b.dataset.mode;values.password='';values.confirm='';values.captcha='';notice='';error='';history.replaceState(null,'','#'+mode);refreshCaptcha();});
 root.querySelector('#auth-reveal').onclick=()=>{rememberValues();showPassword=!showPassword;render();root.querySelector('#auth-password').focus();};
 root.querySelector('#auth-captcha-refresh').onclick=()=>{rememberValues();refreshCaptcha();};
 root.querySelector('#auth-form').onsubmit=submit;
 }
 async function refreshCaptcha(){const n=++version;captchaBusy=true;challenge=null;values.captcha='';render();try{const r=await client('/api/auth/captcha');if(!r.ok)throw new Error('network');const body=await r.json();if(alive&&n===version)challenge=body;}catch{if(alive&&n===version)error='network';}finally{if(alive&&n===version){captchaBusy=false;render();}}}
 async function submit(e){e.preventDefault();if(busy||!challenge)return;rememberValues();error='';notice='';if(mode==='register'&&values.password!==values.confirm){error='mismatch';render();return;}busy=true;const current=mode,payload={username:values.username,password:values.password,captcha:values.captcha,captchaId:challenge.id,remember:values.remember};render();try{const r=await client('/api/auth/'+current,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),body=await r.json();if(!alive)return;if(!r.ok)throw new Error(body.error?.code??'network');if(current==='register'){mode='login';history.replaceState(null,'','#login');values.password='';values.confirm='';notice='success';}else{values.password='';alive=false;onLogin?.(body.user);return;}}catch(e){if(alive)error=words.zh[e.message]?e.message:'network';}finally{if(alive){busy=false;await refreshCaptcha();}}}
 render();refreshCaptcha();return ()=>{alive=false;version++;values.password='';values.confirm='';};
}
